import sys
import math

def is_power_of_two(n):
    return (n & (n - 1)) == 0

def lexicographicallySmallest(S, k):
    n = len(S)
    if is_power_of_two(n):
        k //= 2
    else:
        k *= 2

    if k > n:
        return -1

    stack = []
    for char in S:
        while k and stack and stack[-1] > char:
            stack.pop()
            k -= 1
        stack.append(char)

    # If there are still characters to remove, remove from the end
    while k:
        stack.pop()
        k -= 1

    return ''.join(stack)

def main():
    import sys
    input = sys.stdin.read().splitlines()
    S = input[0]
    k = int(input[1])
    result = lexicographicallySmallest(S, k)
    print(result)

if __name__ == "__main__":
    main()
